/**
 * pack 多位方法的**第 2 位**与第 1 位同判（S500，把 S498 ⑥ 那句「第二位以后没量」结掉）：
 * `tmp/d6/s500a.py` 四百四十格 = `PackedByteArray` 与 `PackedStringArray` 两面 × `set` / `insert` / `find` /
 * `slice` / `bsearch` 五位 × 廿二型 × 两种实参写法（字面量与形参标注名），读数同名 `.json`。
 * 引擎拒三百八十格：八支标量与值型的字面量两句齐发，`Array` / `Dictionary` / 九支 pack 只回第二句，
 * 名字形一律只回第二句（二百二十组里与字面量形剥掉 AS 后差额 0）；收的六十格正是槽型 widen 得进的那几档 ——
 * `PackedStringArray` 的 e 位连 `NodePath` 一起收，与 S498 补的那一名一致。出货在 S498 落地时就是按槽表通用做的，
 * 这一族零改动对上。
 */
import { describe, it } from "vitest";
import { eq } from "@gds2js/testkit";
import { analyze } from "@gds2js/compiler/lower/analyze";
import { lower } from "@gds2js/compiler/lower/lower";
import { parseSource } from "@gds2js/compiler/parse/parser";

async function msgs(body: string): Promise<string[]> {
  const src = "extends SceneTree\n\n" + body;
  return analyze(lower(await parseSource(src))).diagnostics.map((d) => d.message).sort();
}

